# Enable all standard intents and message content
# (prefix commands generally require message content)
intents = Intents.default()
intents.message_content = True

client = commands.Bot(command_prefix='.' , case_insensitive=True, intents=intents)
llm_client = genai.Client(api_key=GEMINI_KEY)

@client.event
async def on_ready():
	await client.change_presence(activity=discord.Activity(type=discord.ActivityType.watching, name='ChatGPT Logs'))
	print("Ready")

@client.command(aliases=['tim'])
async def timbot_dialog(ctx, *, dialog_sentence):
	print("Received: " + dialog_sentence)
	# pass string of dialog_sentence into your code

	try:
		dialog_response = timbot.timResponse(dialog_sentence, llm_client, ctx.author)
	except:
		dialog_response = "I am having some issues with my brain right now, ask me something else."

	# response
	await ctx.send(f"{ctx.author.mention} {dialog_response}")
	

if __name__ == "__main__":
	client.run(KEY)